function findPonds(H, surf) {
let filled = pondPass(H, surf, true);
PONDS.left.length = 0;
filled += pondPass(H, surf, false);
if (filled) {
for (const t of W.trees) t.y = heightAt(t.x, t.z);
for (const r of W.rocks) r.y = heightAt(r.x, r.z);
}
